INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Japonia', 'Nopți de neon, temple liniștite și arta micilor detalii.', 'Japonia este locul unde orașe ultramoderne stau lângă altare vechi de o mie de ani. Fiecare tren vine la timp, fiecare masă e o mică ceremonie, iar fiecare anotimp pictează țara într-o altă culoare.', 'Sfârșitul lui martie - mai (cireșii în floare) și octombrie - noiembrie (frunzele de toamnă)' FROM destination WHERE slug = 'japan';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Un oraș de 14 milioane de locuitori care încă pare o colecție de cartiere mici, fiecare cu personalitatea lui.', 'Tokyo are mai multe restaurante cu stele Michelin decât orice alt oraș din lume - iar unele sunt doar niște tejghele minuscule, cu mai puțin de 10 locuri.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Intersecția Shibuya noaptea', 'Privește până la 3.000 de oameni traversând deodată de pe terasa Shibuya Sky, apoi alătură-te și tu mulțimii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Senso-ji la răsărit', 'Cel mai vechi templu din Tokyo, în Asakusa, liniștit și aurit înainte să sosească mulțimile.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Mic dejun la Tsukiji Outer Market', 'Tamagoyaki, sushi proaspăt și scoici la grătar, mâncate în picioare lângă tarabe.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Mergi desculț prin apă și prin camere cu oglinzi într-un muzeu imersiv de artă digitală.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Muntele Fuji / Hakone', 'Izvoare termale, o corabie de pirați pe lacul Ashi și - într-o zi senină - Fuji în toată splendoarea lui.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Panorama orașului Tokyo' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Felinare seara' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.sort_order = 1;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Muntele Fuji văzut de la Pagoda Chureito' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.sort_order = 2;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Vechea capitală imperială: case de lemn machiya, grădini cu mușchi și felinare care strălucesc pe ulițe înguste.', 'Kyoto are peste 1.600 de temple budiste și aproximativ 400 de altare șintoiste. A fost cruțat de bombardamente în al Doilea Război Mondial datorită valorii sale culturale.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Plimbă-te la răsărit printre miile de porți torii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Pădurea de bambus Arashiyama și Tenryu-ji', 'Bambuși uriași, apoi o grădină zen aflată în patrimoniul mondial UNESCO.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Gion la apus', 'Plimbă-te pe străzile luminate de felinare și poate zărești o geiko sau o maiko în drum spre o întâlnire.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Kinkaku-ji, Pavilionul de Aur', 'Un templu acoperit cu foiță de aur, oglindit perfect în iazul din fața lui.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'O ceremonie a ceaiului sau o cină kaiseki', 'Încetinește ritmul cu un matcha într-o cameră cu tatami sau cu un festin sezonier cu multe feluri.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Pagoda Yasaka' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Felinare în Gion' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Bucătăria Japoniei: gălăgioasă, prietenoasă și obsedată de street food.', 'Motto-ul neoficial al orașului Osaka este „kuidaore” - mănâncă până cazi.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur de street food în Dotonbori', 'Takoyaki, okonomiyaki și kushikatsu sub celebra reclamă Glico cu omulețul care aleargă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Castelul Osaka', 'Urcă în castel pentru priveliștea asupra orașului și plimbă-te pe lângă șanțurile cu apă mărginite de cireși.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Piața Kuromon', 'Frigărui de wagyu la grătar și căpșuni uriașe, direct de la tarabă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Nara', 'Înclină-te în fața căprioarelor prietenoase și vezi statuia uriașă a lui Buddha din Todai-ji.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Umeda Sky Building la apus', 'Un observator în aer liber, o „grădină plutitoare” la 173 m deasupra orașului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Osaka noaptea' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Partea tropicală a Japoniei: apă turcoaz, recife de corali și o cultură insulară relaxată.', 'Okinawa este una dintre „Zonele Albastre” ale lumii, cu unul dintre cele mai mari numere de centenari de pe Pământ.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling în Insulele Kerama', 'Una dintre cele mai limpezi ape din lume, cu broaște țestoase marine drept companie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Acvariul Churaumi', 'Rechini-balenă care alunecă prin fața unuia dintre cele mai mari geamuri de acvariu din lume.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Castelul Shuri', 'Reședința lăcuită în roșu a vechiului Regat Ryukyu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu mașina pe podul spre insula Kouri', 'Un pod de doi kilometri care pare să plutească deasupra apelor turcoaz, puțin adânci.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Bucătărie tradițională din Okinawa', 'Goya champuru și cartof dulce mov - dieta longevității.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta din Okinawa' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Nordul sălbatic al Japoniei: zăpadă pufoasă, câmpuri de lavandă și izvoare termale aburinde.', 'În Niseko, pe Hokkaido, cad în jur de 15 metri de zăpadă pe sezon - una dintre cele mai pufoase zăpezi de pe planetă.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Schi sau snowboard în Niseko', 'Zăpadă pufoasă celebră în toată lumea, cu Muntele Yotei înălțându-se în spatele pârtiilor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Festivalul Zăpezii din Sapporo', 'Sculpturi uriașe de gheață în fiecare februarie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Câmpurile de lavandă din Furano', 'Dealuri mov de la sfârșitul lui iunie până la începutul lui august.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Onsen în Noboribetsu', 'Relaxează-te în izvoare cu sulf, lângă aburinda „Vale a Iadului”.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Fructe de mare proaspete în Otaru', 'Boluri cu uni, crab și icre de somon într-un orășel-port cu canale.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Hokkaido iarna' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.sort_order = 0;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Islanda', 'Foc, gheață și aurora boreală dansând deasupra ta.', 'Islanda pare o altă planetă: plaje cu nisip negru, ghețari, gheizere și cascade după fiecare curbă a șoselei Ring Road. Vara soarele abia apune; iarna cerul se aprinde în verde.', 'Iunie - august (soarele de la miezul nopții, road trip-uri) și septembrie - martie (aurora boreală)' FROM destination WHERE slug = 'iceland';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Cea mai nordică capitală din lume: case colorate, cafenele primitoare și o scenă creativă plină de viață.', 'Reykjavik funcționează aproape în întregime cu energie regenerabilă, geotermală și hidro - chiar și unele trotuare sunt încălzite ca să topească zăpada.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Turnul Hallgrimskirkja', 'Urcă în biserica inspirată de coloanele de bazalt pentru o priveliște peste acoperișurile în culorile curcubeului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Sky Lagoon la apus', 'O piscină geotermală tip infinity, cu vedere spre ocean.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Sala de concerte Harpa', 'Un fagure de sticlă în port, care strălucește noaptea.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Observarea balenelor din Portul Vechi', 'Balene minke, balene cu cocoașă și papagali de mare, vara.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'În căutarea aurorei boreale', 'Ieși din luminile orașului într-o noapte senină de iarnă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Acoperișurile din Reykjavik' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Aurora deasupra golfului' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Cercul de Aur', 'O buclă de 300 km cu trei dintre cele mai faimoase minuni naturale ale Islandei.', 'La Thingvellir poți face snorkeling în Silfra, o fisură între plăcile tectonice nord-americană și eurasiatică.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling în fisura Silfra', 'Apă de ghețar atât de limpede încât vezi la peste 100 m - între două continente.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Gheizerul Strokkur', 'Erupe la fiecare 5 - 10 minute și aruncă apa până la 30 m înălțime.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cascada Gullfoss', 'O cascadă tunătoare în două trepte, adesea cu un curcubeu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Cea mai veche piscină naturală din Islanda, aburind în mijlocul câmpului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Craterul Kerid', 'Un crater vulcanic roșu, cu un lac albastru-verzui pe fund.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Peisaje din Cercul de Aur' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Coasta de Sud (Vik)', 'Cascade, ghețari și plaje cu nisip negru de-a lungul șoselei Ring Road.', 'Nisipul negru de pe Reynisfjara provine din lavă care s-a răcit instantaneu când a atins apele reci ale Atlanticului.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Pe după cascada Seljalandsfoss', 'O potecă te poartă chiar prin spatele perdelei de apă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Urcă cele peste 500 de trepte pentru priveliștea de sus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja cu nisip negru Reynisfjara', 'Coloane de bazalt și stânci în mare - dar ai grijă la valurile neașteptate („sneaker waves”).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Drumeție pe ghețarul Solheimajokull', 'Colțari, piolet și crevase de gheață albastră, alături de un ghid.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Laguna glaciară Jokulsarlon', 'Aisberguri care plutesc spre „Plaja Diamantelor”.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta de Sud' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Numită „Islanda în miniatură” - o peninsulă cu câte puțin din toate.', 'Jules Verne a ales ghețarul Snaefellsjokull drept intrare în „Călătorie spre centrul Pământului”.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Muntele Kirkjufell', 'Cel mai fotografiat munte din Islanda, cu cascade în față.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Falezele de la Arnarstapi', 'O plimbare pe coastă, pe lângă arcade de bazalt și păsări care își fac cuiburile.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Biserica neagră de la Budir', 'O biserică neagră și singuratică într-un câmp de lavă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Peștera de lavă Vatnshellir', 'Coboară 35 m într-un tunel de lavă vechi de 8.000 de ani.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja Djupalonssandur', 'Pietricele negre și rămășițe de epave pe un țărm sălbatic.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Kirkjufell sub aurora boreală' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Nordul (Akureyri)', 'Capitala nordului și poarta spre lacul Myvatn și ținutul balenelor.', 'Semafoarele din Akureyri au lumina roșie în formă de inimă - o mică campanie pentru a-i înveseli pe oameni după criza din 2008.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Observarea balenelor în Husavik', 'Capitala europeană a observării balenelor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Lacul Myvatn', 'Pseudocratere, formațiuni de lavă și bazine de noroi care bolborosesc.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Verișoara mai liniștită, albastru-lăptoasă, a celebrei Blue Lagoon.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, '„Cascada zeilor”, o potcoavă perfectă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Cea mai puternică cascadă din Europa.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Nordul Islandei' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri' AND x.sort_order = 0;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Maroc', 'Piețe de mirodenii, ulițe albastre și nopți sub stelele Saharei.', 'Marocul este o sărbătoare a simțurilor: chemarea la rugăciune deasupra medinei, ceai de mentă turnat de la înălțime, riaduri ascunse în spatele unor uși simple și dune care strălucesc portocaliu la apus.', 'Martie - mai și septembrie - noiembrie (temperaturi blânde, nu prea cald în deșert)' FROM destination WHERE slug = 'morocco';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Orașul Roșu: souk-uri pline de viață, palate și apusuri privite de pe terase.', 'În fiecare seară, piața Jemaa el-Fnaa se transformă într-un food court în aer liber, cu povestitori, muzicieni și peste 100 de tarabe cu mâncare - o „Capodoperă a patrimoniului imaterial” UNESCO.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Jemaa el-Fnaa la amurg', 'Privește cum se transformă piața de pe terasa unei cafenele, apoi pierde-te printre tarabele cu mâncare.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Vila albastru-cobalt și grădina de cactuși care au aparținut cândva lui Yves Saint Laurent.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Rătăcește-te prin souk-uri', 'Piele, felinare, mirodenii - și arta tocmelii prietenoase.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cazare într-un riad + hammam', 'O casă cu curte interioară și fântână, plus o exfoliere tradițională în baia de aburi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi în Munții Atlas', 'Sate berbere, cascade și prânz cu priveliște.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Medina din Marrakech' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Curtea unui riad' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Inima culturală a Marocului și cel mai vechi dintre orașele sale imperiale.', 'Fes el-Bali este cea mai mare zonă urbană fără mașini din lume - mărfurile sunt cărate încă cu măgarul pe cele peste 9.000 de ulițe.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tăbăcăria Chouara', 'Vezi cum se vopsește pielea în cuve de piatră, la fel ca acum 900 de ani.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Fondată în 859, este considerată cea mai veche universitate încă existentă din lume.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Madrasa Bou Inania', 'Cedru sculptat, plăci zellige și stuc - o capodoperă a artei merinide.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plimbare cu ghid prin medina', 'Un ghid local este cea mai bună cale de a găsi atelierele ascunse.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus de la Mormintele Merinide', 'Întreaga medina strălucește sub tine.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes' AND x.rank_no = 5;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Celebra perlă albastră din Munții Rif.', 'Nimeni nu știe sigur de ce orașul e albastru - teoriile spun că ține țânțarii departe, că răcorește casele sau că simbolizează cerul și paradisul.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Fotografiază ulițele albastre', 'Mergi dimineața devreme pentru străzi goale și lumină blândă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Belvederea de la Moscheea Spaniolă', 'O drumeție scurtă pentru apusul deasupra întregului oraș albastru.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cascadele Akchour', 'Bazine turcoaz și arcada de piatră numită „Podul lui Dumnezeu”.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Ceai de mentă și brânză de capră în piața principală.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Izvorul Ras el-Maa', 'Locul unde localnicii încă spală lâna și hainele în pârâul de munte.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Ulițe albastre' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Dunele Erg Chebbi - de până la 150 m înălțime, strălucind portocaliu la apus.', 'Sahara are cam aceeași suprafață ca SUA, dar doar în jur de un sfert din ea sunt dune de nisip - restul sunt platouri stâncoase și câmpii cu pietriș.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plimbare cu cămila la apus', 'Intră în dune în timp ce trec de la auriu la un portocaliu intens.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'O noapte într-o tabără în deșert', 'Tobe berbere lângă foc și mai multe stele decât ai văzut vreodată.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Răsăritul din vârful unei dune', 'Merită urcușul de dimineață, de fiecare dată.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Ca snowboardul, dar la cald.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cheile Todra, pe drum', 'Pereți de canion de până la 300 m înălțime.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara' AND x.rank_no = 5;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Un oraș-port alb și răcoros, bătut de vânt, la malul Atlanticului.', 'Zidurile din Essaouira au fost locul de filmare pentru Astapor din „Urzeala tronurilor”.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Meterezele Skala de la Ville', 'Tunuri vechi și valuri care se sparg de ziduri la apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Pește la grătar în port', 'Îl alegi de la tarabă și ți-l fac la grătar pe loc.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Alizeele fac din Essaouira unul dintre cele mai bune locuri de kitesurfing din Africa.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cooperativă de ulei de argan', 'Vezi cum cooperativele de femei fac ulei de argan manual.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Călărie pe plajă', 'Galopează de-a lungul golfului larg și nisipos.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta Atlanticului' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira' AND x.sort_order = 0;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Thailanda', 'Temple aurii, insule de explorat și cel mai bun street food de pe Pământ.', 'De la agitația din Bangkok la junglele și templele din nord și insulele de calcar din sud. Thailanda este Țara Zâmbetelor: piețe de noapte, bărci long-tail, orez lipicios cu mango și unele dintre cele mai frumoase plaje din Asia.', 'Noiembrie - aprilie (sezonul uscat pe coasta Andaman: Phuket, Krabi, Phi Phi); noiembrie - februarie este perioada cea mai răcoroasă' FROM destination WHERE slug = 'thailand';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'O capitală care nu se oprește niciodată: temple aurii, bărci pe râu, baruri pe acoperișuri și street food la fiecare colț.', 'Numele ceremonial complet al orașului Bangkok, care începe cu „Krung Thep Maha Nakhon”, este cel mai lung nume de localitate din lume - thailandezii îi spun simplu Krung Thep, „Orașul Îngerilor”.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Marele Palat și Wat Phra Kaew', 'Fosta reședință regală, uluitoare, și templul lui Buddha de Smarald. Acoperă-ți umerii și genunchii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Wat Pho și Wat Arun', 'Vezi statuia de 46 m a lui Buddha culcat, apoi ia feribotul peste râu până la Wat Arun pentru apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Street food noaptea în Chinatown', 'Strada Yaowarat se aprinde cu reclame de neon și tarabe cu tăiței, fructe de mare și orez lipicios cu mango.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu barca long-tail pe canale', 'Explorează canalele (khlong) din Thonburi și vezi casele de lemn pe piloni și partea veche a orașului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Piața de weekend Chatuchak', 'Una dintre cele mai mari piețe din lume, cu mii de tarabe - mergi devreme, că se face cald.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Templele din Bangkok' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Străzile orașului' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Capitala relaxată a nordului: un oraș vechi înconjurat de ziduri, temple pe munte și cursuri de gătit.', 'Chiang Mai are peste 300 de temple budiste - aproape cât Bangkokul, într-un oraș de multe ori mai mic.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Urcă scara străjuită de naga, de aproximativ 300 de trepte, până la templul auriu de pe munte, cu priveliște peste oraș.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Un sanctuar etic pentru elefanți', 'Hrănește elefanți salvați și plimbă-te alături de ei, într-un sanctuar care nu oferă plimbări în spinarea lor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Curs de gătit thailandez', 'Fă cumpărături într-o piață locală, apoi pregătește-ți singur pasta de curry, pad thai și orez lipicios cu mango.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templele din Orașul Vechi, cu bicicleta', 'Pedalează între Wat Chedi Luang, Wat Phra Singh și templele liniștite din interiorul vechiului șanț de apărare.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Piața de duminică Walking Street', 'Obiecte meșteșugărești, supă khao soi și muzică live pe strada Ratchadamnoen, în fiecare duminică seara.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Munții din nord' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Detalii de templu' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Cea mai mare insulă a Thailandei: plaje lungi cu nisip, un oraș vechi colorat și excursii cu barca în golful Phang Nga.', 'Phuket s-a îmbogățit din mineritul de staniu, care a adus negustori chinezi și europeni - de aceea Orașul Vechi e plin de case-magazin colorate, în stil sino-portughez.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Golful Phang Nga și Insula James Bond', 'Turnuri de calcar care se ridică din apa de smarald, celebre datorită filmului „Omul cu pistolul de aur”.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Orașul Vechi din Phuket', 'Case-magazin în culori pastel, street art și cafenele pe strada Thalang, plus o piață de noapte duminica.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Marele Buddha', 'Un Buddha de 45 m din marmură albă, pe vârful unui deal, cu priveliște spre golful Chalong.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus la Capul Promthep', 'Vârful sudic al insulei, unde toată lumea se adună să vadă soarele coborând în mare.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Scufundări sau snorkeling în Insulele Similan', 'Bolovani de granit și una dintre cele mai limpezi ape din Thailanda (parcul e deschis aproximativ din octombrie până în mai).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta Andaman' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Golful Phang Nga' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Faleze spectaculoase de calcar, lagune ascunse și unele dintre cele mai bune trasee de escaladă din lume.', 'Railay se află pe continent, dar este izolat de faleze înalte de calcar - singura cale de a ajunge acolo este cu barca.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja Railay și peștera Phra Nang', 'Nisip alb încadrat de faleze uriașe și o plajă-peșteră plină de ofrande pentru zeița locală a mării.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Turul celor Patru Insule cu barca long-tail', 'Treci de la Poda la Chicken Island și Tup Island, unde la reflux apare o limbă de nisip.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Escaladă în Railay', 'Cursuri potrivite pentru începători, pe pereți de calcar chiar deasupra plajei.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Peșterii Tigrului', 'Peste 1.200 de trepte abrupte până la un Buddha auriu în vârf, cu junglă de jur împrejur. Mergi devreme.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Emerald Pool și izvoarele termale', 'Un bazin turcoaz în pădure, apoi o baie caldă la cascada termală din Khlong Thom.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Faleze de calcar' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Din insulă în insulă' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Insulele Phi Phi', 'Lagune turcoaz, plaje albe și faleze ca din film, la o scurtă călătorie cu feribotul din Phuket sau Krabi.', 'Maya Bay, unde a fost filmat „Plaja” cu Leonardo DiCaprio, a fost închis între 2018 și 2022 ca să se refacă coralii - iar rechinii de recif cu vârful negru s-au întors în golf.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Maya Bay dimineața devreme', 'Vezi celebrul golf înainte să sosească excursiile de o zi. Înotul nu este permis, iar golful se închide o parte din fiecare an.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Drumeție până la Phi Phi Viewpoint', 'Un urcuș transpirat pentru priveliștea clasică asupra celor două golfuri arcuite din Phi Phi Don, cel mai frumos la apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling în laguna Pileh și pe Bamboo Island', 'Înoată într-o lagună de smarald înconjurată de faleze, apoi relaxează-te pe o insulă liniștită cu nisip alb.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu caiacul până la Monkey Beach', 'Vâslește de-a lungul falezelor până la o plajă mică (ai grijă de genți și nu hrăni maimuțele).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus și spectacole cu foc pe Loh Dalum', 'Baruri pe plajă și dansatori cu foc după lăsarea serii - pe insulă nu sunt mașini, așa că mergi peste tot pe jos.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Lagună turcoaz' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta din Phi Phi' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', NULL, 'Orezării în terase, ceremonii la temple și surf la apus.', 'Insula Zeilor, din Indonezia: spirituală, verde și nesfârșit de fotogenică. Mici ofrande de flori stau pe fiecare prag, ceremoniile de la temple umplu străzile de muzică, iar într-o singură zi poți trece de la cascade în junglă la apusuri privite de pe faleze.', 'Aprilie - octombrie (sezonul uscat); mai, iunie și septembrie sunt mai puțin aglomerate decât iulie - august' FROM destination WHERE slug = 'bali';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Inima culturală a Bali, în mijlocul junglei: orezării în terase, yoga, sate de meșteșugari și dans tradițional.', 'Orezăriile în terase din Bali sunt irigate prin „subak”, un sistem cooperativ de irigații administrat de templele apei încă din secolul al IX-lea. Este sit al patrimoniului mondial UNESCO.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Orezăriile Tegallalang la răsărit', 'Plimbă-te pe treptele verzi înainte de căldură și de mulțime - și încearcă faimosul leagăn din junglă, dacă ai chef.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Sanctuarul Pădurea Sacră a Maimuțelor', 'Temple acoperite de mușchi și sute de macaci cu coadă lungă. Ascunde ochelarii de soare și gustările.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plimbare pe creasta Campuhan', 'O potecă ușoară pe o creastă înierbată, între două văi de râu, minunată la răsărit sau la apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul apei Tirta Empul', 'Alătură-te balinezilor într-un ritual de purificare sub izvoarele sfinte. Primești sarong la intrare.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Dans Kecak sau Legong seara', 'Dans tradițional la Palatul din Ubud sau la un templu local, în lumina focului și a felinarelor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Orezării în terase' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Jungla din Ubud' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Vârful sudic și sălbatic al Bali: faleze de calcar, plaje ascunse și surf de clasă mondială.', 'Pura Luhur Uluwatu, cocoțat la aproximativ 70 m deasupra oceanului, este unul dintre cele șase temple principale ale Bali, despre care se crede că protejează insula de spiritele rele.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Uluwatu și dansul Kecak cu foc', 'Un templu pe faleză la apus, urmat de hipnoticul dans cu incantații. Ai grijă la maimuțe.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plajele Padang Padang și Bingin', 'Golfulețe mici la care ajungi pe trepte printre faleze, cu nisip auriu și apă limpede.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Privește surferii sau învață să faci surf', 'Unele dintre cele mai celebre valuri de recif din lume - începătorii pot lua lecții pe plaje mai blânde.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja Melasti', 'Un drum săpat prin faleze albe coboară spre o plajă largă, cu apă turcoaz.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus la un beach club pe faleză', 'Cocktailuri și o piscină infinity deasupra Oceanului Indian.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Falezele din Uluwatu' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Oceanul Indian' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Canggu și Seminyak', 'Coasta de vest a Bali, cea la modă: plaje de surf, cafenele, buticuri și cele mai frumoase apusuri de pe insulă.', 'Canggu a fost o zonă liniștită, cu orezării și câteva locuri de surf, până în anii 2010 - astăzi este unul dintre cele mai populare locuri din lume pentru nomazii digitali.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tanah Lot la apus', 'Un templu al mării, pe o stâncă din ocean - la reflux poți merge până la baza lui.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Lecție de surf la Batu Bolong', 'Valuri blânde și line, perfecte pentru prima ta dată pe placă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Din cafenea în cafenea, la brunch', 'Smoothie bowls, cafea excelentă și mâncare sănătoasă pe fiecare stradă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Buticurile și spa-urile din Seminyak', 'Cumpără de la designeri locali, apoi rezervă un masaj tradițional balinez.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus la Echo Beach sau la un beach club', 'Fotolii-sac pe nisip și muzică live în timp ce cerul se face portocaliu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Apus pe coasta de vest' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Plajă de surf' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'O insulă sălbatică, la o scurtă cursă cu barca rapidă din Bali, celebră pentru falezele spectaculoase și pentru mante (diavoli de mare).', 'Plaja Kelingking are porecla „Golful T-Rex” pentru că, văzută de sus, faleza seamănă cu capul unui Tyrannosaurus.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Belvederea de la Kelingking Beach', 'Celebra faleză T-Rex. Poteca spre plajă este foarte abruptă - coboară doar cu încălțări bune.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling cu mante', 'Înoată alături de mante uriașe la Manta Point sau Manta Bay, într-o excursie cu barca.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'O arcadă naturală de piatră deasupra unui golf circular și, lângă ea, un bazin limpede între stânci (verifică mai întâi valurile).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Trepte săpate în faleză coboară spre nisip alb și apă albastră, pe coasta de est.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Răsărit la belvederea Thousand Islands', 'Un șir de insulițe sub faleze, aurii în lumina dimineții.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Falezele din Nusa Penida' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Apele mantelor' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Malaezia', 'Zgârie-nori, pădure tropicală și o bucătărie modelată de trei culturi.', 'Aromele malaeziene, chinezești și indiene se întâlnesc în orașe, pe insule și într-una dintre cele mai vechi păduri tropicale din lume. Într-o săptămână poți gusta din toate tarabele de street food de sub Turnurile Petronas, iar în următoarea poți privi urangutani sălbatici în Borneo.', 'Decembrie - aprilie pentru coasta de vest (Penang, Langkawi); martie - octombrie pentru Sabah (Borneo); Kuala Lumpur e o alegere bună tot anul' FROM destination WHERE slug = 'malaysia';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Un orizont modern, temple colorate și unele dintre cele mai bune street food-uri din Asia.', 'Cu cei 452 m ai lor, Turnurile Gemene Petronas au fost cele mai înalte clădiri din lume între 1998 și 2004 și sunt încă cele mai înalte turnuri gemene de pe Pământ.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Turnurile Gemene Petronas și Skybridge', 'Traversează podul dintre turnuri, apoi privește-le cum se aprind seara din parcul KLCC. Cumpără biletele din timp.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Peșterile Batu', 'Urcă cele 272 de trepte în culorile curcubeului până la un templu hindus dintr-o peșteră uriașă de calcar, păzit de o statuie aurie gigantică.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Strada cu mâncare Jalan Alor', 'Satay, crab cu chili și durian la sute de tarabe în aer liber, în fiecare seară.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Piața Merdeka și orașul vechi', 'Locul unde a fost proclamată independența în 1957, înconjurat de clădiri în stil maur.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'KL Tower sau un bar pe acoperiș la apus', 'Privește cum întregul oraș devine auriu, apoi sclipește când se aprind luminile.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Orizontul din Kuala Lumpur' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Street food noaptea' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'O insulă celebră pentru străzile istorice din George Town, street art și legendarul street food.', 'Celebrele picturi murale din George Town au fost începute în 2012 de artistul lituanian Ernest Zacharevic, pentru un festival. Trebuiau să fie temporare, iar acum sunt cea mai mare atracție a orașului.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Vânătoare de street art în George Town', 'Găsește picturile murale și caricaturile din fier forjat din orașul vechi aflat în patrimoniul UNESCO - pe jos sau cu bicicleta.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur de street food', 'Char kway teow, assam laksa și cendol pe Gurney Drive sau New Lane - Penang este capitala gastronomică a Malaeziei.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Kek Lok Si', 'Unul dintre cele mai mari temple budiste din Asia de Sud-Est, frumos luminat cu felinare noaptea.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Penang Hill cu funicularul', 'Urcă pe deal pentru aer mai răcoros și o priveliște asupra George Town și a podului spre continent.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Chew Jetty, debarcaderele clanurilor', 'Case de lemn pe piloni deasupra apei, locuite încă de familii ale clanurilor chinezești.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Străzile din George Town' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Templele din Penang' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Un arhipelag tropical relaxat, cu pădure tropicală, mangrove și plaje liniștite.', 'Langkawi este un grup de 99 de insule - la reflux mai apar câteva. Întregul arhipelag este Geoparc Global UNESCO și zonă duty-free.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'SkyCab și Sky Bridge', 'O cursă abruptă cu telecabina pe Muntele Mat Cincang, până la un pod curbat suspendat deasupra pădurii tropicale.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur cu barca sau caiacul prin mangrovele Kilim', 'Alunecă printre mangrove și peșteri de calcar, cu vulturi rotindu-se deasupra.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Din insulă în insulă', 'Înoată în Lacul Fecioarei Însărcinate de pe Dayang Bunting și relaxează-te pe plaja Beras Basah.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cascada Seven Wells', 'O drumeție prin junglă până la bazine naturale de piatră, așezate unul deasupra celuilalt.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus pe Pantai Cenang', 'Cea mai animată plajă a insulei, cu cine cu fructe de mare pe nisip.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Plajele din Langkawi' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Mangrove' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Borneo sălbatic: urangutani, râuri prin pădurea tropicală, Muntele Kinabalu și unele dintre cele mai bune locuri de scufundări din lume.', 'Borneo este a treia insulă ca mărime din lume și singura împărțită între trei țări: Malaezia, Indonezia și Brunei.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Centrul de reabilitare a urangutanilor Sepilok', 'Privește urangutanii salvați cum vin legănându-se la ora mesei, în pădurea tropicală.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Croazieră pe râul Kinabatangan', 'Caută maimuțe nasalis, păsări calao și chiar elefanți pitici, în zori și la amurg.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Urcă sau vizitează Muntele Kinabalu', 'Cel mai înalt vârf al Malaeziei, de 4.095 m - o ascensiune de două zile sau trasee ușoare prin natură în Parcul Kinabalu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Scufundări sau snorkeling la Sipadan', 'Broaște țestoase, tornade de barracuda și rechini de recif. Permisele zilnice sunt limitate, așa că rezervă din timp.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Din insulă în insulă, din Kota Kinabalu', 'Snorkeling în Parcul Tunku Abdul Rahman, apoi apusul și piața de noapte din oraș.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Muntele Kinabalu' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Pădurea tropicală din Borneo' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Singapore', 'Un oraș-grădină al viitorului, cu mâncarea de stradă de altădată.', 'Mic, impecabil de curat și surprinzător de verde, cu cartiere care par fiecare o altă țară. Într-o singură zi poți lua micul dejun în Little India, prânzul la o tarabă cu stea Michelin, te poți plimba pe sub uriașii Supertrees luminați și poți încheia ziua cu o priveliște de pe acoperiș asupra golfului.', 'Februarie - aprilie (mai uscat și mai puțin umed); cald tot anul (aproximativ 25 - 32 C), cu ploi tropicale scurte aproape în orice zi' FROM destination WHERE slug = 'singapore';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Orizontul celebru: Marina Bay Sands, Merlionul și o faleză care se luminează în fiecare seară.', 'O mare parte din Marina Bay este construită pe teren câștigat de la mare - Singapore a crescut cu aproximativ 25% din anii 1960 încoace, adăugând pământ în mare.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Spectacolul de lumini și apă Spectra', 'Un spectacol gratuit, seara, pe promenada de pe malul apei, în fața Marina Bay Sands.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Platforma de observație de la etajul 57, pentru priveliștea clasică asupra golfului și a orașului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Merlionul', 'Simbolul Singapore, jumătate leu, jumătate pește, cu cel mai bun loc pentru poze cu orizontul chiar în spatele lui.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Strada cu satay de la Lau Pa Sat', 'O hală victoriană în fața căreia strada se umple de grătare cu satay în fiecare seară.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plimbare la apus în jurul golfului', 'Traversează podul Helix și urmează promenada în timp ce zgârie-norii se aprind.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Orizontul Marina Bay' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Golful la amurg' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'marina-bay' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Insula de joacă a Singapore: plaje, parcuri de distracții și telecabine, chiar după un pod scurt.', 'Sentosa înseamnă „pace și liniște” în malaeziană, dar insula se numea cândva Pulau Blakang Mati - „insula din spatele morții” - și a fost un fort militar britanic.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Atracții și spectacole în zone tematice - mergi într-o zi lucrătoare ca să eviți cele mai lungi cozi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Telecabina de pe Muntele Faber', 'Plutește deasupra portului și a navelor până pe insulă, cu priveliște înapoi spre oraș.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plajele Siloso și Palawan', 'Relaxează-te pe nisip și traversează podul suspendat până la o insuliță de lângă plaja Palawan.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Unul dintre cele mai mari acvarii din lume, cu un geam uriaș plin de mante și rechini.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Explorează tuneluri vechi și tunuri din al Doilea Război Mondial, în vârful vestic al insulei.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Plajele din Sentosa' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Apele insulei' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'sentosa' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Chinatown și Little India', 'Cartiere istorice colorate, pline de temple, case-magazin, mirodenii și cu unele dintre cele mai bune mâncăruri din oraș.', 'În 2016, o tarabă cu pui în sos de soia din Chinatown a devenit una dintre primele tarabe de street food din lume care au primit o stea Michelin.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Relicvei Dintelui lui Buddha', 'Un templu impunător, roșu cu auriu, în Chinatown, cu o grădină liniștită pe acoperiș.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Încearcă orezul cu pui Hainanese, felul național al Singapore, la unul dintre cele mai celebre centre de street food.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Sri Mariamman', 'Cel mai vechi templu hindus din Singapore, cu un turn acoperit de zei sculptați în culori vii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tekka Centre și strada Serangoon', 'Biryani, ghirlande de flori și magazine de mirodenii în inima cartierului Little India.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Kampong Glam și Haji Lane', 'Moscheea aurie a Sultanului, Arab Street și ulițe înguste pline de picturi murale și buticuri mici.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Străzi istorice' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Temple și case-magazin' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'chinatown-little-india' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Grădini și natură', '„Orașul într-o grădină”: grădini futuriste, plimbări prin pădurea tropicală și una dintre cele mai bune grădini zoologice din lume.', 'Grădina Botanică din Singapore are peste 160 de ani și a fost prima grădină botanică tropicală inclusă în patrimoniul mondial UNESCO.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Gardens by the Bay și Supertrees', 'Plimbă-te pe pasarela OCBC Skyway printre uriașii Supertrees, apoi rămâi seara la spectacolul de lumini Garden Rhapsody.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cloud Forest și Flower Dome', 'Un munte în interior, cu o cascadă de 35 m, și cea mai mare seră de sticlă din lume.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Grădina Botanică din Singapore', 'Intrare gratuită, iar Grădina Națională a Orhideelor are peste 1.000 de specii de orhidee.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Prima grădină zoologică de noapte din lume - vezi animalele treze după lăsarea întunericului, cu trenulețul sau pe o potecă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Southern Ridges și Henderson Waves', 'O plimbare printre coroanele copacilor, de-a lungul unui lanț de parcuri de 10 km și peste podul în formă de val Henderson Waves.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Gardens by the Bay' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Singapore verde' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'singapore' AND p.slug = 'gardens-nature' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', NULL, 'Vulcani, curcubeie și adevăratul spirit aloha.', 'Un stat american în mijlocul Pacificului, la peste 3.000 km de cel mai apropiat continent. Fiecare insulă are personalitatea ei: Oahu e plină de viață, Maui te relaxează, Big Island este încă în construcție datorită lavei, iar Kauai este junglă verde în stare pură.', 'Aprilie - mai și septembrie - octombrie (vreme uscată, mai puțină aglomerație, prețuri mai bune); decembrie - aprilie pentru balenele cu cocoașă' FROM destination WHERE slug = 'hawaii';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Locul de întâlnire: viața de oraș din Honolulu, plaja Waikiki și surful legendar de pe North Shore.', 'Palatul Iolani din Honolulu este singurul palat regal de pe teritoriul SUA - a fost casa ultimilor monarhi hawaiieni și a avut lumină electrică înaintea Casei Albe.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Diamond Head la răsărit', 'O drumeție scurtă și abruptă pe un vechi crater vulcanic, cu priveliște asupra Waikiki și a oceanului. Rezervă-ți din timp intervalul de intrare.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Pearl Harbor și Memorialul USS Arizona', 'O vizită liniștită și emoționantă la locul care a atras SUA în al Doilea Război Mondial.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'O zi pe North Shore', 'Iarna, privește surferii pe valurile uriașe, apoi mănâncă creveți cu usturoi de la un food truck din Haleiwa.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling în Hanauma Bay', 'Un golf protejat în interiorul unui con vulcanic, plin de pești de recif și broaște țestoase verzi. Rezervarea este obligatorie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Valea verde și spectaculoasă unde s-au filmat „Jurassic Park” și „Jumanji” - cu jeepul, călare sau cu bicicleta electrică.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta din Oahu' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Apă turcoaz' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Insula Văii: răsărit deasupra norilor, drumuri șerpuite pe coastă și balene iarna.', 'Haleakala înseamnă „Casa Soarelui”. Legenda spune că semizeul Maui a prins soarele cu lasoul din vârful muntelui, ca să facă zilele mai lungi.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Răsărit pe Haleakala', 'Privește soarele răsărind deasupra unei mări de nori, de la 3.000 m. Intrarea la răsărit trebuie rezervată din timp - ia-ți o geacă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Drumul spre Hana', 'Sute de curbe, poduri cu o singură bandă, cascade, plaje cu nisip negru și tarabe cu pâine cu banane.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling la craterul Molokini', 'Un crater vulcanic pe jumătate scufundat, cu una dintre cele mai limpezi ape din Hawaii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Observarea balenelor (decembrie - aprilie)', 'Mii de balene cu cocoașă vin în apele calde ale insulei Maui ca să nască.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja Kaanapali și Black Rock', 'Snorkeling cu broaște țestoase la Black Rock, apoi rămâi pentru ceremonia săriturii de pe stâncă, la apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Plajă în Maui' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Deasupra norilor' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Cea mai tânără și cea mai mare insulă, unde vulcanii activi încă adaugă pământ nou.', 'Măsurat de la baza sa de pe fundul oceanului, Mauna Kea are peste 10.000 m înălțime - mai mult decât Everestul.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Parcul Național Hawaii Volcanoes', 'Plimbă-te pe lângă fumarole și cratere în jurul vulcanului Kilauea - noaptea, verifică dacă se vede strălucirea lavei.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling de noapte cu mante în Kona', 'Plutește la suprafață în timp ce mante uriașe fac tumbe în luminile de sub tine.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Observarea stelelor pe Mauna Kea', 'Unul dintre cele mai bune locuri de pe Pământ pentru a vedea stelele, unde se află observatoare de top mondial.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja cu nisip negru Punaluu', 'Nisip vulcanic negru ca smoala, cu broaște țestoase verzi odihnindu-se pe mal (păstrează distanța).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur la o plantație de cafea Kona', 'Gustă una dintre cele mai celebre cafele din lume chiar acolo unde crește, pe versanții vulcanului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Peisaj vulcanic' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Cerul nopții' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Insula Grădină: cea mai veche dintre insulele principale, numai faleze de smarald, cascade și plaje liniștite.', 'Pe Kauai nicio clădire nu poate fi mai înaltă decât un cocotier - o regulă locală care păstrează insula sălbatică și fără clădiri înalte.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Coasta Na Pali cu barca sau elicopterul', 'Faleze verzi abrupte care coboară în ocean, accesibile doar pe mare, din aer sau printr-o drumeție lungă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Canionul Waimea', 'Poreclit „Marele Canion al Pacificului” - stâncă roșie, creste verzi și cascade.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Golful Hanalei', 'O semilună largă de nisip, cu munți în spate. Perfectă pentru o zi leneșă la plajă sau pentru paddleboarding.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Traseul Kalalau până la Hanakapiai', 'Prima parte a celebrului traseu de coastă. Rezervă din timp intrarea în Parcul de Stat Haena.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu caiacul pe râul Wailua', 'Vâslește prin junglă, apoi urcă până la o cascadă pentru o baie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta Na Pali' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Canionul Waimea' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Egipt', 'Faraoni, Nilul și recife de corali în Marea Roșie.', '5.000 de ani de istorie de-a lungul Nilului, plus unele dintre cele mai bune locuri de scufundări din lume. Stai în fața ultimei Minuni a Lumii Antice care a supraviețuit, navighează cu o feluca la apus, intră în mormintele pictate din Valea Regilor, apoi înoată cu broaște țestoase în Marea Roșie.', 'Octombrie - aprilie (mai răcoros pentru temple și deșert); Marea Roșie e bună tot anul. În jurul datelor de 22 februarie și 22 octombrie, soarele luminează sanctuarul interior de la Abu Simbel' FROM destination WHERE slug = 'egypt';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Cairo și Giza', 'O capitală uriașă, gălăgioasă și fascinantă, cu Piramidele de la Giza așteptând la marginea deșertului.', 'Marea Piramidă de la Giza a fost cea mai înaltă construcție făcută de om de pe Pământ timp de aproximativ 3.800 de ani și este singura dintre cele Șapte Minuni ale Lumii Antice care mai există.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Piramidele și Sfinxul la deschidere', 'Ajungi devreme ca să scapi de căldură și de mulțime, apoi mergi la punctul panoramic pentru priveliștea clasică asupra tuturor celor nouă piramide.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Marele Muzeu Egiptean', 'Uriașul muzeu nou de lângă piramide, unde se află întreaga comoară a lui Tutankhamon. Planifică cel puțin o jumătate de zi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Saqqara și Piramida în trepte a lui Djoser', 'Cea mai veche piramidă din Egipt, plus morminte frumos pictate, cu mult mai puțini vizitatori decât la Giza.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Khan el-Khalili și Cairoul islamic', 'Pierde-te prin vechiul bazar, apoi bea un ceai de mentă la El Fishawy, o cafenea deschisă de peste 200 de ani.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu feluca pe Nil la apus', 'O barcă tradițională cu pânze, din lemn, în timp ce se aprind luminile orașului pe ambele maluri.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Piramidele de la Giza' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Egiptul antic' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Vechea Teba, numită adesea cel mai mare muzeu în aer liber din lume: temple pe malul estic, morminte regale pe cel vestic.', 'Mormântul lui Tutankhamon din Valea Regilor a fost descoperit aproape neatins de Howard Carter în 1922 - mumia lui se odihnește acolo și astăzi.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Zbor cu balonul cu aer cald la răsărit', 'Plutește deasupra templelor de pe malul vestic, a câmpurilor verzi ale Nilului și a munților deșertului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Valea Regilor', 'Intră în morminte regale colorate, săpate adânc în stâncă. Pentru cele mai celebre ai nevoie de bilete suplimentare.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Karnak', 'Unul dintre cele mai mari complexe religioase construite vreodată - Marea Sală Hipostilă are 134 de coloane uriașe.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul din Luxor noaptea', 'Templul și Aleea Sfincșilor, frumos luminate după apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul Hatșepsut și Colosii lui Memnon', 'Templul în terase al uneia dintre puținele femei faraon ale Egiptului și, pe drum, doi uriași de piatră de 18 m.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Templele din Luxor' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Răsărit deasupra malului vestic' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Cel mai liniștit loc de pe Nil: insule de granit, sate nubiene colorate și poarta spre Abu Simbel.', 'În anii 1960, templele de la Abu Simbel au fost tăiate în blocuri și mutate cu 65 m mai sus, bucată cu bucată, ca să fie salvate de apele în creștere ale lacului Nasser.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Abu Simbel', 'Templele colosale ale lui Ramses al II-lea, lângă granița cu Sudanul. Plecare foarte devreme, dar merită pe deplin.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Templul de la Philae', 'Templul insular al zeiței Isis, la care ajungi cu o barcă mică - și el salvat și mutat din calea Nilului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu feluca în jurul insulei Elephantine', 'Navighează pe lângă bolovani de granit și Insula Botanică a lui Kitchener, în lumina de după-amiază târziu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Vizită într-un sat nubian', 'Case pictate în culori vii, henna, mirodenii și o primire călduroasă pe malul vestic.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Croazieră pe Nil până la Luxor', 'Trei sau patru zile lente pe râu, cu opriri la templele din Kom Ombo și Edfu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Nilul la Aswan' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Abu Simbel' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Marea Roșie', 'Apă caldă și limpede și recife de corali colorate de-a lungul coastei de la Hurghada, El Gouna și Marsa Alam.', 'Marea Roșie este una dintre cele mai sărate mări din lume și găzduiește peste 1.000 de specii de pești - multe dintre ele nu se găsesc nicăieri altundeva pe Pământ.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling în Insulele Giftun', 'O excursie cu barca din Hurghada până la insule cu nisip alb și grădini de corali în apă mică.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Înot cu broaște țestoase în Marsa Alam', 'În golful Abu Dabbab, broaștele țestoase verzi se hrănesc cu iarbă de mare aproape de plajă - și uneori apare și un dugong.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Scufundare la epava SS Thistlegorm', 'O navă de marfă din al Doilea Război Mondial plină de motociclete și camioane, una dintre cele mai celebre scufundări la epave din lume (pentru scafandri brevetați).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Safari în deșert și cină beduină', 'Cu ATV-ul sau jeepul spre munți, apoi cină și privit stelele în deșert.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Kitesurf sau relaxare în El Gouna', 'Un oraș-lagună fără mașini, cu vânt constant, bărci-taxi și restaurante pe malul apei.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta Mării Roșii' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Ape cu recife de corali' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Italia', 'Vârfuri zimțate în nord, golfulețe turcoaz în sud și istorie la fiecare colț.', 'La dolce vita în toate formele ei: drumeții sub vârfurile roz ale Dolomiților, înot în golfulețele albastre ca în Caraibe ale Sardiniei, orecchiette mâncate pe ulițele vechi din Bari, o plimbare prin 2.000 de ani de istorie la Roma și, desigur, sprijinitul Turnului înclinat din Pisa.', 'Mai - iunie și septembrie - octombrie pentru orașe și litoral (cald, mai puțină aglomerație); sfârșitul lui iunie - septembrie pentru drumeții în Dolomiți; decembrie - martie pentru schi' FROM destination WHERE slug = 'italy';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Dolomiții', 'Vârfuri palide de calcar, pajiști alpine și cabane montane cu strudel și mămăligă, în nordul Italiei.', 'La apus, Dolomiții se colorează adesea în roz și portocaliu - localnicii numesc fenomenul „enrosadira”. Roca conține dolomit, un mineral numit după geologul francez Deodat de Dolomieu.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Bucla Tre Cime di Lavaredo', 'O drumeție clasică de o jumătate de zi în jurul celor trei vârfuri celebre, cu plecare de la Rifugio Auronzo (drum cu taxă, mergi devreme).' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Lago di Braies la răsărit', 'Un lac de smarald sub pereți abrupți - închiriază o barcă de lemn cu vâsle înainte să vină mulțimea.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Creasta Seceda', 'Ia telecabina din Ortisei până pe una dintre cele mai spectaculoase creste din Alpi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Cea mai mare pajiște de altitudine din Europa, perfectă pentru plimbări ușoare, ciclism sau schi iarna.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Prânz la un rifugio', 'Cabane montane cu terase însorite, găluște canederli și strudel cu mere, cu priveliște.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Vârfurile Dolomiților' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Lac alpin' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Sardinia', 'O insulă cu golfulețe turcoaz, nisip alb și turnuri străvechi de piatră, în mijlocul Mediteranei.', 'Sardinia are peste 7.000 de nuraghi - turnuri misterioase de piatră construite acum mai bine de 3.000 de ani. Este și una dintre „Zonele Albastre” ale lumii, unde mulți oameni trec de 100 de ani.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie cu barca în Golful Orosei', 'Golfulețe ascunse precum Cala Goloritze și Cala Mariolu, la care ajungi doar cu barca sau pe o potecă abruptă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plaja La Pelosa', 'Apă mică, limpede ca cristalul, lângă Stintino. Vara rezervă-ți intrarea din timp și ia o saltea de plajă - prosoapele nu sunt permise.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Arhipelagul La Maddalena', 'Navighează printre insule de granit roz, cu una dintre cele mai limpezi ape din Mediterana.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Cel mai bine păstrat sat nuragic de pe insulă, sit al patrimoniului mondial UNESCO.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus în Alghero', 'Plimbă-te pe vechile ziduri de la mare ale acestui oraș cu aer catalan, apoi cină cu fructe de mare locale.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta Sardiniei' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Golfulețe turcoaz' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Capitala plină de viață a regiunii Puglia: un oraș vechi plin de femei care fac paste, o faleză lungă și baza perfectă pentru a explora sudul.', 'Osemintele Sfântului Nicolae - sfântul care l-a inspirat pe Moș Crăciun - au fost aduse la Bari de marinari în 1087 și se odihnesc și azi în Bazilica San Nicola.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Bari Vecchia și „strada pastelor”', 'Privește femeile din cartier făcând orecchiette de mână, în fața ușilor, pe Strada Arco Basso.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Bazilica San Nicola', 'O biserică romanică frumoasă și un important loc de pelerinaj atât pentru catolici, cât și pentru ortodocși.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur de street food', 'Panzerotti, sgagliozze (mămăligă prăjită) și focaccia barese, proaspete, din orașul vechi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Polignano a Mare', 'Case albe pe faleze deasupra mării și celebra plajă Lama Monachile.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Casele trulli din Alberobello', 'Un oraș ca din povești, cu case albe de piatră și acoperișuri conice, sit UNESCO la aproximativ o oră distanță.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Orașul vechi din Bari' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta din Puglia' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Roma', 'Cetatea Eternă: ruine antice, fântâni baroce, Vaticanul și cine lungi în piațete pavate cu piatră.', 'În fiecare zi sunt aruncați în Fontana di Trevi monede de aproximativ 3.000 de euro. Banii sunt strânși și donați în scopuri caritabile - iar tradiția spune că o monedă înseamnă că te vei întoarce la Roma.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Colosseumul și Forumul Roman', 'Pășește pe unde au luptat gladiatorii și au vorbit senatorii. Cumpără din timp, online, bilete cu oră fixă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Muzeele Vaticanului și Capela Sixtină', 'Plafonul lui Michelangelo și Bazilica Sfântul Petru. Mergi devreme sau târziu ca să eviți cele mai lungi cozi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Fontana di Trevi și Panteonul în zori', 'Vezi-le aproape goale, înainte să se trezească orașul, apoi bea un espresso în picioare, la bar.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Trastevere noaptea', 'Ulițe acoperite de iederă, cacio e pepe și carbonara într-o trattorie de familie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Galeria și grădinile Borghese', 'Sculpturi de Bernini înăuntru, apoi apusul deasupra orașului de pe terasa Pincio.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Roma' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Străzile Romei' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Mult mai mult decât celebrul turn: un oraș universitar plin de viață pe malul râului Arno, aproape de Florența, Lucca și coasta Toscanei.', 'Turnul a început să se încline încă din timpul construcției, în secolul al XII-lea, din cauza terenului moale. Între 1990 și 2001, inginerii au redus înclinarea cu aproximativ 45 cm, așa că ar trebui să rămână în picioare secole de acum înainte.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Urcă în Turnul înclinat', 'Aproximativ 250 de trepte ușor înclinate până în vârf. Biletele au oră fixă, așa că rezervă din timp.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Catedrala din marmură albă, Baptisteriul și cimitirul monumental din jurul turnului, toate pe o pajiște verde.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plimbare de-a lungul râului Arno', 'Cheiurile „lungarni” la apus, cu palate colorate și mica biserică gotică Santa Maria della Spina.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Lucca', 'Pedalează pe zidurile renascentiste ale orașului, la doar 30 de minute cu trenul.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Florența sau coasta Toscanei', 'O oră până la arta și mâncarea din Florența sau mergi spre plajele din Viareggio și Cinque Terre.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Piazza dei Miracoli' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Râul Arno la apus' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Norvegia', 'Fiorduri, sate de pescari și aurora boreală.', 'Fiorduri spectaculoase, căsuțe roșii pe malul apei și aventuri arctice dincolo de cercul polar. Norvegia este locul unde dimineața iei trenul prin munți, după-amiaza vâslești cu caiacul pe un fiord, iar noaptea aștepți să se facă cerul verde.', 'Iunie - august (fiorduri, drumeții, soarele de la miezul nopții) și sfârșitul lui septembrie - martie (aurora boreală)' FROM destination WHERE slug = 'norway';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'O capitală verde și relaxată, la malul apei, cu muzee de clasă mondială și saune chiar pe fiord.', 'Premiul Nobel pentru Pace este singurul premiu Nobel acordat în afara Suediei - este decernat în fiecare an, pe 10 decembrie, la Primăria din Oslo.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plimbare pe acoperișul Operei', 'Acoperișul înclinat din marmură albă se ridică direct din fiord - urcă până sus pentru apus.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Parcul de sculpturi Vigeland', 'Peste 200 de sculpturi de Gustav Vigeland în parcul Frogner, gratuit și deschis toată ziua.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Muzeul MUNCH', 'Opera lui Edvard Munch, inclusiv versiuni ale „Țipătului”, într-o clădire spectaculoasă din port.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Muzeele din Bygdoy, cu feribotul', 'Nave polare la Muzeul Fram și pluta lui Thor Heyerdahl la Muzeul Kon-Tiki.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Saună plutitoare pe fiord', 'Încălzește-te într-o saună pe apă, apoi sari în fiord - în stil norvegian, tot anul.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Portul din Oslo' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Fiordul Oslo' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Bergen și fiordurile', 'Colorata cetate-port hanseatică și poarta spre cele mai celebre fiorduri ale Norvegiei.', 'Bergen este unul dintre cele mai ploioase orașe din Europa, cu ploaie în peste 200 de zile pe an - localnicii glumesc că bebelușii de aici se nasc cu umbrela.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cheiul Bryggen', 'Rătăcește pe aleile înguste din spatele caselor colorate de lemn ale negustorilor, sit al patrimoniului mondial UNESCO.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Funicularul Floibanen până pe Muntele Floyen', 'Urci în câteva minute pentru priveliștea clasică asupra orașului, apoi cobori pe jos prin pădure.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Calea ferată Flam și croazieră pe Naeroyfjord', 'Una dintre cele mai abrupte căi ferate cu ecartament normal din lume, apoi o croazieră pe unul dintre cele mai înguste fiorduri.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Drumeție la Trolltunga (vara)', 'O drumeție lungă și grea de o zi până la celebra limbă de stâncă suspendată la 700 m deasupra lacului Ringedalsvatnet.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Prânz la Piața de pește', 'Creveți proaspeți, crab-rege și supă de pește chiar în port.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Priveliște spre fiord' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Munți deasupra fiordului' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Vârfuri zimțate care se ridică direct din mare, căsuțe roșii de pescari și plaje arctice cu nisip alb.', 'Lofoten se află dincolo de Cercul Polar, dar datorită Curentului Golfului iernile sunt mult mai blânde decât în alte locuri la fel de nordice.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Reine și Hamnoy la ora de aur', 'Priveliștea de carte poștală: căsuțe roșii, apă liniștită și vârfuri ascuțite - cel mai bine de pe poduri.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Drumeție pe Reinebringen', 'Aproximativ 2.000 de trepte de piatră până la unul dintre cele mai celebre puncte de belvedere din Norvegia.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Dormi într-un rorbu', 'O cabană tradițională de pescari, pe piloni deasupra apei.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Surf arctic la Unstad', 'Surf sub soarele de la miezul nopții sau sub aurora boreală, cu un costum de neopren gros.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Muzeul Vikingilor Lofotr', 'O reconstituire a celei mai mari case lungi vikinge descoperite vreodată, cu un ospăț viking vara.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Sat de pescari în Lofoten' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Vârfuri arctice' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Capitala Arcticii și una dintre cele mai bune baze din lume pentru a vedea aurora boreală.', 'În Tromso soarele nu răsare deloc de la sfârșitul lui noiembrie până la mijlocul lui ianuarie (noaptea polară) și nu apune de la sfârșitul lui mai până la sfârșitul lui iulie (soarele de la miezul nopții).' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'În căutarea aurorei boreale', 'Tururi în grupuri mici care fug de nori și de luminile orașului ca să găsească aurora.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Sanie cu câini husky', 'Condu-ți propria echipă de câini prin văi înzăpezite.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Telecabina Fjellheisen', 'Urcă la Storsteinen, la 421 m deasupra orașului, pentru priveliște la apus sau sub aurora boreală.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Observarea balenelor (noiembrie - ianuarie)', 'Orcele și balenele cu cocoașă urmăresc heringii în fiordurile nordice, iarna.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Reni și cultura sami', 'Hrănește reni și ascultă cântece joik și povești într-un cort lavvu, lângă foc.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Aurora boreală' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Iarnă arctică' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso' AND x.sort_order = 1;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', NULL, 'Nopți de tango, cascade tunătoare și ghețari pe care îi auzi cum crapă.', 'Argentina este uriașă - a opta țară ca mărime din lume - și fiecare colț al ei pare altfel. Dansează tango pe străzile elegante din Buenos Aires, stai în stropii Cascadelor Iguazu, savurează un Malbec la poalele Anzilor în Mendoza și privește cum pereți de gheață se prăbușesc în lac la ghețarul Perito Moreno.', 'Octombrie - aprilie pentru Patagonia; martie - mai (culesul viei) pentru Mendoza; martie - mai și septembrie - noiembrie pentru Buenos Aires; Iguazu e bun tot anul (mai ploios și cu mai multă apă în decembrie - martie)' FROM destination WHERE slug = 'argentina';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Poarta spre Parcul Național Los Glaciares, ghețarul Perito Moreno și El Chalten, capitala drumețiilor.', 'Ghețarul Perito Moreno este unul dintre puținii ghețari din lume care nu se micșorează - are aproximativ 30 km lungime, iar fruntea lui se ridică la circa 70 m deasupra lacului Lago Argentino.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Pasarelele de la ghețarul Perito Moreno', 'Privește cum blocuri uriașe de gheață se desprind și se prăbușesc în lac, de pe balcoanele aflate chiar în fața ghețarului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Mini-trekking pe gheață', 'Pune-ți colțarii și mergi chiar pe ghețar, printre crevase albastre.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la El Chalten și Laguna de los Tres', 'O drumeție lungă și grea până la priveliștea emblematică a Muntelui Fitz Roy la răsărit.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu barca la ghețarii Upsala și Spegazzini', 'Navighează pe Lago Argentino printre aisberguri uriașe, până la ghețari la care ajungi doar pe apă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Miel patagonez la o estancia', 'Cordero al asador, copt încet, la o fermă tradițională de oi, cu gauchos și priveliști nesfârșite.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Ghețarul Perito Moreno' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'patagonia-el-calafate' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, '„Parisul Americii de Sud”: bulevarde grandioase, cartiere colorate, cine târzii și tango până la răsărit.', 'Avenida 9 de Julio este unul dintre cele mai late bulevarde din lume, cu până la 7 benzi pe fiecare sens - îți trebuie mai multe semafoare ca să-l traversezi.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tango în San Telmo', 'Duminica privește dansatorii din Plaza Dorrego, apoi ia o lecție sau mergi seara la o milonga.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'La Boca și Caminito', 'Case pictate în culori vii, street art și celebrul stadion al echipei Boca Juniors. Vizitează-l ziua.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cimitirul Recoleta', 'Un oraș de morminte și statui din marmură, unde este înmormântată Eva Peron.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Un adevărat asado argentinian', 'Friptură de vită și Malbec la o parrilla tradițională - cina începe rareori înainte de ora 21.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'O librărie într-un teatru vechi, numită adesea una dintre cele mai frumoase din lume.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Străzile din Buenos Aires' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Arhitectură grandioasă' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'buenos-aires' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Cascadele Iguazu', 'Aproximativ 275 de cascade în junglă, la granița cu Brazilia, una dintre cele Șapte Noi Minuni ale Naturii.', 'Se spune că Eleanor Roosevelt, când a văzut prima dată Iguazu, ar fi exclamat „Bietul Niagara!” - Iguazu este mai înalt decât Niagara și de aproximativ două ori mai lat.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Garganta del Diablo (Gâtlejul Diavolului)', 'Ia trenulețul prin junglă și mergi pe pasarele peste râu până la marginea celei mai mari și mai zgomotoase cascade.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Circuitele de sus și de jos', 'Pasarele deasupra și dedesubtul cascadelor, cu curcubeie aproape oriunde te uiți.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu barca pe sub cascade', 'O barcă rapidă te duce direct în stropi - te vei uda complet.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Partea braziliană', 'O excursie de o zi peste graniță pentru priveliștea panoramică largă asupra întregului sistem de cascade.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Observarea animalelor', 'Tucani, coati și nori de fluturi pe potecile din pădure. Ține-ți gustările ascunse de coati.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Cascadele Iguazu' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Junglă subtropicală' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'iguazu-falls' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Capitala vinului din Argentina, cu podgorii la poalele Anzilor și cel mai înalt munte din cele două Americi în apropiere.', 'Mendoza produce cea mai mare parte a vinului argentinian, iar Aconcagua, aflat în apropiere, este cel mai înalt munte din afara Asiei, cu 6.961 m.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Degustare de Malbec în Valea Uco', 'Podgorii la mare altitudine, cu Anzii înzăpeziți chiar în spatele lor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu bicicleta printre cramele din Maipu', 'Închiriază o bicicletă și mergi din bodega în bodega, cu degustări de ulei de măsline pe drum.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Parcul Provincial Aconcagua', 'O plimbare scurtă până la punctul de belvedere spre cel mai înalt munte din cele două Americi.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Băile termale de la Cacheuta', 'Bazine cu apă caldă lângă un râu de munte, perfecte după o zi lungă de degustări.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Prânz lung la o cramă', 'O masă cu mai multe feluri, asortată cu vinuri locale - planifică o după-amiază, nu o oră.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Podgorii la poalele Anzilor' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'argentina' AND p.slug = 'mendoza' AND x.sort_order = 0;
INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', NULL, 'De la cel mai arid deșert de pe Pământ la turnurile de granit ale Patagoniei.', 'Chile are aproximativ 4.300 km lungime și, în medie, sub 200 km lățime, strâns între Anzi și Pacific. Forma aceasta îi dă aproape toate peisajele de pe planetă: saline și gheizere în nord, podgorii și o capitală plină de viață la mijloc, iar jos, la capătul lumii, ghețari, fiorduri și vârfuri sălbatice în Patagonia.', 'Octombrie - aprilie pentru Patagonia (decembrie - februarie e cel mai cald, dar și cel mai vântos); septembrie - noiembrie și martie - mai pentru Santiago; deșertul Atacama e bun tot anul' FROM destination WHERE slug = 'chile';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Turnuri de granit, lacuri turcoaz, ghețari albaștri și guanaco sălbatici, într-unul dintre cele mai spectaculoase parcuri naționale de pe Pământ.', 'Se spune adesea că „Paine” înseamnă „albastru” în limba poporului tehuelche - un nume potrivit pentru un parc plin de ghețari albaștri și lacuri turcoaz.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Drumeție până la Mirador Las Torres', 'O drumeție lungă și abruptă de o zi până la cele trei celebre turnuri de granit de deasupra unui lac glaciar. Pornește devreme pentru strălucirea de la răsărit.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Traseul W', 'Trekul clasic de 4 - 5 zile prin parc, cu nopți în refugii sau la camping. Rezervă-le cu luni înainte.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu barca la ghețarul Grey', 'Navighează pe Lago Grey printre aisberguri plutitoare, până la fruntea ghețarului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Animale sălbatice și pe urmele pumei', 'Guanaco, condori și nandu sunt peste tot - cu un ghid specializat poți zări chiar și o pumă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Puerto Natales și Peștera Milodonului', 'Un orășel-port primitor, bun de odihnă după drumeții, și o peșteră uriașă unde s-au găsit rămășițele unui leneș gigant preistoric.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Torres del Paine' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Lacuri glaciare' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'patagonia' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'O capitală modernă, cu Anzii înzăpeziți drept fundal, piețe excelente cu mâncare și podgorii chiar la marginea orașului.', 'Iarna poți schia dimineața în Anzi și privi apusul deasupra Pacificului în aceeași seară - ambele sunt la doar aproximativ 1,5 ore de Santiago.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Urcă pe deal cu funicularul sau cu telecabina pentru cea mai bună priveliște asupra orașului și a Anzilor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Valparaiso', 'Un oraș-port colorat, cu dealuri, street art și funiculare vechi, sit al patrimoniului mondial UNESCO.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Degustare de vin în valea Maipo sau Casablanca', 'Carmenere și Cabernet în podgorii aflate la mai puțin de o oră de oraș.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Bellavista și La Chascona', 'Cartierul boem și casa jucăușă a poetului Pablo Neruda.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Mercado Central și La Vega', 'Tocănițe cu fructe de mare, empanadas și fructe proaspete în cele mai animate piețe ale orașului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Străzile din Santiago' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Anzii deasupra orașului' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'santiago-de-chile' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', 'Deșertul Atacama', 'Saline, gheizere, lagune cu flamingi și unele dintre cele mai senine ceruri nocturne din lume, în jurul oazei San Pedro de Atacama.', 'Atacama este cel mai arid deșert nepolar de pe Pământ - unele stații meteo de acolo nu au înregistrat niciodată ploaie. NASA a testat aici roverele marțiene.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Apus în Valle de la Luna', 'Plimbă-te printre dune și formațiuni de sare care seamănă cu suprafața Lunii, în timp ce cerul se face roz.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Gheizerele El Tatio la răsărit', 'Gheizere aburinde la aproximativ 4.300 m - în zori e foarte frig, așa că ia haine groase.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur de observare a stelelor', 'Datorită aerului uscat și altitudinii mari, în Atacama se află unele dintre cele mai mari observatoare din lume.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Plutește în Laguna Cejar', 'O lagună atât de sărată încât plutești fără efort, ca în Marea Moartă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Lagune altiplanice și flamingi', 'Lacuri de un albastru intens la Miscanti și Miniques și flamingi care se hrănesc în Salar de Atacama.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Peisaj de deșert' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Cerul nopții în Atacama' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'chile' AND p.slug = 'atacama-desert' AND x.sort_order = 1;
